# FÁJL: flake.nix
{
  description = "JAIDE V35: Root-Level Non-Transformer Polyglot LLM with FMRN Architecture";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";
    flake-utils.url = "github:numtide/flake-utils";
    zig-overlay.url = "github:mitchellh/zig-overlay";
    rust-overlay.url = "github:oxalica/rust-overlay";
    clash-nix.url = "github:clash-lang/clash-nix";
    sbt-derivation.url = "github:zaninime/sbt-derivation";
    kframework.url = "github:kframework/k";
  };

  outputs = { self, nixpkgs, flake-utils, ... }@inputs:
    flake-utils.lib.eachDefaultSystem (system:
      let
        overlays = [
          inputs.zig-overlay.overlays.default
          inputs.rust-overlay.overlays.default
        ];
        pkgs = import nixpkgs {
          inherit system overlays;
          config.allowUnfree = true;
        };

        jaide-build-tools = with pkgs; [
          zig."0.12.0"
          julia-bin
          elixir_1_15
          ponyc
          nim
          crystal
          chapel
          futhark
          (haskell.packages.ghc965.override {
            overrides = self: super: {
              clash-lib = self.callCabal2nix "clash-lib" inputs.clash-nix {};
              clash-ghc = self.callCabal2nix "clash-ghc" inputs.clash-nix {};
            };
          }).clash-ghc
          (sbt.override {
            jre = jdk17;
          })
          yosys
          nextpnr-ecp5
          trellis
          swiProlog
          lean4
          agda
          isabelle
          tla-plus-bin
          spin
          kframework
          circom
          python311
          python311Packages.numpy
          python311Packages.qiskit
          doxygen
          graphviz
        ];

        jaide-package = pkgs.stdenv.mkDerivation rec {
          pname = "jaide-v35";
          version = "35.0.0";
          src = ./.;

          nativeBuildInputs = jaide-build-tools;

          buildPhase = ''
            export JAIDE_ROOT=$PWD
            bash $JAIDE_ROOT/build.sh
          '';

          installPhase = ''
            mkdir -p $out/bin $out/lib $out/share/jaide
            cp -r build/* $out/share/jaide/
            ln -s $out/share/jaide/bin/jaide-run $out/bin/jaide-run
            echo "JAIDE V35 installation complete."
          '';

          meta = {
            description = "JAIDE V35 Full Build Artifact";
            license = pkgs.lib.licenses.mit;
          };
        };

      in {
        packages.default = jaide-package;

        devShells.default = pkgs.mkShell {
          buildInputs = jaide-build-tools ++ (with pkgs; [
            elixir-ls
            zls
            haskell-language-server
            metals
          ]);
          shellHook = ''
            export JAIDE_ROOT=$PWD
            export LD_LIBRARY_PATH=$LD_LIBRARY_PATH:$JAIDE_ROOT/build/lib
            echo "JAIDE V35 development shell loaded."
            cowsay "Welcome, developer. The Celestial Engines await your command."
          '';
        };

        apps.default = flake-utils.lib.mkApp {
          drv = jaide-package;
          exe = "bin/jaide-run";
        };
      }
    );
}
```

