# FÁJL: build.sh
#!/bin/bash
set -euo pipefail

# --- Configuration and Environment Setup ---
ROOT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
BUILD_DIR="$ROOT_DIR/build"
SRC_DIR="$ROOT_DIR/src"
HARDWARE_DIR="$SRC_DIR/hardware"
GPU_DIR="$SRC_DIR/gpu"
PARALLEL_DIR="$SRC_DIR/parallel"
VERIFICATION_DIR="$SRC_DIR/verification"
ZK_DIR="$BUILD_DIR/zk"
CONFIG_DIR="$ROOT_DIR/config"
LIB_NAME="libjaidev35.so"

# ANSI Color Codes
GREEN='\033[0;32m'
RED='\033[0;31m'
YELLOW='\033[1;33m'
NC='\033[0m' # No Color

echo -e "${GREEN}--- JAIDE V35 Build Process Initializing ---${NC}"
echo "Root Directory: $ROOT_DIR"
echo "Source Directory: $SRC_DIR"
echo "Build Directory: $BUILD_DIR"

# Create directory structure
mkdir -p "$BUILD_DIR"/{verilog,bin,lib,include,tests,docs,zk,verification_logs,hardware_bitstreams,formal_proofs}

# --- Phase 0: Environment Validation and Setup ---
echo -e "\n${YELLOW}--- Phase 0: Environment Validation and Setup ---${NC}"
declare -A tools
tools=(
    [zig]="Zig compiler" [julia]="Julia" [elixir]="Elixir" [ponyc]="Pony compiler"
    [nim]="Nim compiler" [crystal]="Crystal compiler" [chpl]="Chapel compiler"
    [futhark]="Futhark compiler" [ghc]="GHC (for Clash)" [sbt]="SBT"
    [yosys]="Yosys" [nextpnr-ecp5]="nextpnr-ecp5" [prjtrellis]="Project Trellis"
    [swipl]="SWI-Prolog" [lean]="Lean 4" [agda]="Agda" [isabelle]="Isabelle"
    [tlc]="TLC (TLA+)" [spin]="SPIN" [kore-exec]="K Framework" [circom]="Circom"
    [python3]="Python 3" [qiskit]="Qiskit (via Python)"
)

for tool in "${!tools[@]}"; do
    if ! command -v "$tool" &> /dev/null; then
        echo -e "${RED}ERROR: ${tools[$tool]} ('$tool') not found. Please ensure it's in your PATH.${NC}"
        exit 1
    fi
done
echo -e "${GREEN}INFO: All critical tools detected. Proceeding with build.${NC}"

# --- Phase 1: Compiling Core Numerics & Runtime (Zig) ---
