pub const DType = enum { f64, f32, i64, i32, c64, c32 };

pub const Shape = []const usize;

pub fn totalElements(shape: Shape) usize {
    if (shape.len == 0) return 1;
    var total: usize = 1;
    for (shape) |dim| {
        total *= dim;
    }
    return total;
}

pub const Tensor = struct {
    allocator: Allocator,
    data: []u8,
    shape: Shape,
    strides: []usize,
    dtype: DType = .f64,
    offset: usize = 0,
    is_view: bool = false,
    requires_grad: bool = false,
    grad: ?*Tensor = null,

    pub fn init(allocator: Allocator, shape: Shape, dtype: DType) !*Tensor {
        const self = try allocator.create(Tensor);
        const total = totalElements(shape);
        const data_type_size = @sizeOf(typeFromDType(dtype));

        self.* = .{
            .allocator = allocator,
            .data = try allocator.alloc(u8, total * data_type_size),
            .shape = try allocator.dupe(usize, shape),
            .strides = try computeStrides(allocator, shape),
            .dtype = dtype,
            .is_view = false,
        };
        @memset(self.data, 0);
        return self;
    }

    pub fn deinit(self: *Tensor) void {
        if (!self.is_view) {
            self.allocator.free(self.data);
            self.allocator.free(self.shape);
            self.allocator.free(self.strides);
        }
        if (self.grad) |g| {
            g.deinit();
            self.allocator.destroy(g);
        }
        self.allocator.destroy(self);
    }

    pub fn getPtr(self: *const Tensor, indices: []const usize) !*anyopaque {
        if (indices.len != self.shape.len) return error.IndexDimensionMismatch;
        var idx: usize = self.offset;
        for (indices, self.strides) |dim, stride| {
            idx += dim * stride;
        }
        const data_type_size = @sizeOf(typeFromDType(self.dtype));
        return &self.data[idx * data_type_size];
    }

    pub fn get(self: *const Tensor, indices: []const usize) !f64 {
        if (self.dtype != .f64) return error.DataTypeMismatch;
        const ptr = try self.getPtr(indices);
        return @ptrCast(*const f64, @alignCast(ptr)).*;
    }

    pub fn set(self: *Tensor, indices: []const usize, value: f64) !void {
        if (self.dtype != .f64) return error.DataTypeMismatch;
        const ptr = try self.getPtr(indices);
        @ptrCast(*f64, @alignCast(ptr)).* = value;
    }

    pub fn view(self: *const Tensor, allocator: Allocator, new_shape: Shape) !*Tensor {
        if (totalElements(self.shape) != totalElements(new_shape)) {
            return error.ShapeMismatch;
        }
        const new_view = try allocator.create(Tensor);
        new_view.* = .{
            .allocator = self.allocator, // Views share the original allocator
            .data = self.data,
            .shape = try allocator.dupe(usize, new_shape),
            .strides = try computeStrides(allocator, new_shape),
            .dtype = self.dtype,
            .offset = self.offset,
            .is_view = true,
            .requires_grad = self.requires_grad,
            .grad = self.grad,
        };
        return new_view;
    }

    pub fn clone(self: *const Tensor, allocator: Allocator) !*Tensor {
        const new_tensor = try Tensor.init(allocator, self.shape, self.dtype);
        @memcpy(new_tensor.data, self.data);
        return new_tensor;
    }

    pub fn matmul(self: *const Tensor, other: *const Tensor, allocator: Allocator) !*Tensor {
        if (self.shape.len != 2 or other.shape.len != 2 or self.shape[1] != other.shape[0]) {
            return error.ShapeMismatch;
        }
        if (self.dtype != .f64 or other.dtype != .f64) return error.DataTypeMismatch;

        const m = self.shape[0];
        const n = other.shape[1];
        const k = self.shape[1];
        const result = try Tensor.init(allocator, &.{m, n}, .f64);

        const self_data: [*]const f64 = @ptrCast([*]const f64, @alignCast(self.data.ptr));
        const other_data: [*]const f64 = @ptrCast([*]const f64, @alignCast(other.data.ptr));
        const result_data: [*]f64 = @ptrCast([*]f64, @alignCast(result.data.ptr));

        for (0..m) |i| {
            for (0..n) |j| {
                var sum: f64 = 0.0;
                for (0..k) |l| {
                    sum += self_data[i * self.strides[0] + l * self.strides[1]] * other_data[l * other.strides[0] + j * other.strides[1]];
                }
                result_data[i * result.strides[0] + j * result.strides[1]] = sum;
            }
        }
        return result;
    }

    pub fn add(self: *const Tensor, other: *const Tensor, allocator: Allocator) !*Tensor {
        if (!std.mem.eql(usize, self.shape, other.shape)) return error.ShapeMismatch;
        const result = try self.clone(allocator);
        const total = totalElements(self.shape);
        const self_data: [*]const f64 = @ptrCast([*]const f64, @alignCast(self.data.ptr));
        const other_data: [*]const f64 = @ptrCast([*]const f64, @alignCast(other.data.ptr));
        const result_data: [*]f64 = @ptrCast([*]f64, @alignCast(result.data.ptr));
        var i: usize = 0;
        while (i < total) : (i += 1) {
             result_data[i] = self_data[i] + other_data[i];
        }
        return result;
    }

    pub fn s4d_step(A: *const Tensor, B: *const Tensor, C: *const Tensor, u: f64, h_prev: *const Tensor, dt: f64) !*Tensor {
        // A, B, C, h_prev must be vectors
        // Discretize A: A_bar = exp(dt * A)
        const A_bar = try A.clone(A.allocator);
        const A_bar_data: [*]f64 = @ptrCast([*]f64, @alignCast(A_bar.data.ptr));
        const A_data: [*]const f64 = @ptrCast([*]const f64, @alignCast(A.data.ptr));
        for (0..A.shape[0]) |i| A_bar_data[i] = math.exp(dt * A_data[i]);
        defer A_bar.deinit();

        // Discretize B: B_bar = (A_bar - 1) / A * B
        const B_bar = try B.clone(B.allocator);
        // Simplification for stability: B_bar = dt * B
        const B_bar_data: [*]f64 = @ptrCast([*]f64, @alignCast(B_bar.data.ptr));
        const B_data: [*]const f64 = @ptrCast([*]const f64, @alignCast(B.data.ptr));
        for (0..B.shape[0]) |i| B_bar_data[i] = dt * B_data[i];
        defer B_bar.deinit();

        // h' = A_bar * h + B_bar * u
        const h_new = try A_bar.mul(h_prev, A_bar.allocator);
        const h_new_data: [*]f64 = @ptrCast([*]f64, @alignCast(h_new.data.ptr));
        for (0..h_new.shape[0]) |i| h_new_data[i] += B_bar_data[i] * u;

        // y = C * h'
        const y = try C.mul(h_new, C.allocator);
        // This is simplified, real dot product needed for vector C
        const y_val = @ptrCast([*]const f64, @alignCast(y.data.ptr))[0];
        defer y.deinit();

        return h_new;
    }
};

fn typeFromDType(dtype: DType) type {
    return switch (dtype) {
        .f64 => f64,
        .f32 => f32,
        .i64 => i64,
        .i32 => i32,
        .c64 => @Vector(2, f64),
        .c32 => @Vector(2, f32),
    };
}

fn computeStrides(allocator: Allocator, shape: Shape) ![]usize {
    if (shape.len == 0) return try allocator.alloc(usize, 0);
    const strides = try allocator.alloc(usize, shape.len);
    strides[shape.len - 1] = 1;
    var i = shape.len - 1;
    while (i > 0) : (i -= 1) {
        strides[i - 1] = strides[i] * shape[i];
    }
    return strides;
}

