defmodule JAIDE.Manager do
  use GenServer
  require Logger

  @name __MODULE__

  # --- Public API ---

  def start_link(config) do
    GenServer.start_link(__MODULE__, config, name: @name)
  end

  def submit_task(task) do
    GenServer.cast(@name, {:new_task, task})
  end

  def get_metrics() do
    GenServer.call(@name, :get_metrics)
  end

  # --- GenServer Callbacks ---

  @impl true
  def init(config) do
    Logger.info("JAIDE Actor Manager initializing...")
    num_workers = Keyword.get(config, :num_workers, System.schedulers_online())

    workers =
      for i <- 1..num_workers do
        {:ok, pid} = JAIDE.Worker.start_link(id: i)
        {i, pid}
      end
      |> Map.new()

    Process.send_after(self(), :report_metrics, 10_000)

    state = %{
      workers: workers,
      task_queue: :queue.new(),
      idle_workers: Map.keys(workers),
      completed_tasks: 0,
      metrics: %{queue_length: 0, avg_completion_time: 0.0},
      config: config
    }
    {:ok, state}
  end

  @impl true
  def handle_cast({:new_task, task}, state) do
    new_queue = :queue.in({task, System.monotonic_time(:millisecond)}, state.task_queue)
    new_state = %{state | task_queue: new_queue}
    dispatch_tasks(new_state)
  end

  @impl true
  def handle_info({:worker_ready, worker_pid}, state) do
    case Map.to_list(state.workers) |> Enum.find(fn {_, pid} -> pid == worker_pid end) do
      {worker_id, _} ->
        new_idle_workers = [worker_id | state.idle_workers] |> Enum.uniq()
        new_state = %{state | idle_workers: new_idle_workers}
        dispatch_tasks(new_state)
      nil ->
        Logger.warn("Received ready signal from unknown worker: #{inspect(worker_pid)}")
        {:noreply, state}
    end
  end

  @impl true
  def handle_info({:task_complete, worker_pid, result, start_time}, state) do
    completion_time = System.monotonic_time(:millisecond) - start_time
    new_completed = state.completed_tasks + 1

    # Update metrics
    q_len = :queue.len(state.task_queue)
    old_avg = state.metrics.avg_completion_time
    new_avg = (old_avg * state.completed_tasks + completion_time) / new_completed
    new_metrics = %{queue_length: q_len, avg_completion_time: new_avg}

    Logger.info("Task completed by #{inspect(worker_pid)} in #{completion_time}ms. Result: #{inspect(result)}. Total completed: #{new_completed}")

    case Map.to_list(state.workers) |> Enum.find(fn {_, pid} -> pid == worker_pid end) do
        {worker_id, _} ->
            new_idle_workers = [worker_id | state.idle_workers] |> Enum.uniq()
            new_state = %{state | 
                idle_workers: new_idle_workers, 
                completed_tasks: new_completed,
                metrics: new_metrics
            }
            dispatch_tasks(new_state)
        nil ->
            Logger.warn("Received completion from unknown worker: #{inspect(worker_pid)}")
            {:noreply, state}
    end
  end

  @impl true
  def handle_info(:report_metrics, state) do
    Logger.info("Current Metrics: #{inspect(state.metrics)}")
    Process.send_after(self(), :report_metrics, 10_000)
    {:noreply, state}
  end

  @impl true
  def handle_call(:get_metrics, _from, state) do
    {:reply, state.metrics, state}
  end

  # --- Private Functions ---

  defp dispatch_tasks(state) do
    case {state.idle_workers, :queue.out(state.task_queue)} do
      {[], _} ->
        # No idle workers
        {:noreply, state}
      {_, {:empty, _}} ->
        # No tasks in queue
        {:noreply, state}
      {[worker_id | rest_idle], {{:value, {task, start_time}}, new_queue}} ->
        worker_pid = state.workers[worker_id]
        GenServer.cast(worker_pid, {:run_task, task, start_time})
        new_state = %{state | task_queue: new_queue, idle_workers: rest_idle}
        # Immediately try to dispatch more tasks
        dispatch_tasks(new_state)
    end
  end
end

defmodule JAIDE.Worker do
  use GenServer
  require Logger

  # --- Public API ---
  def start_link(opts) do
    id = Keyword.fetch!(opts, :id)
    GenServer.start_link(__MODULE__, id, name: via_tuple(id))
  end

  # --- GenServer Callbacks ---
  @impl true
  def init(id) do
    Logger.info("Worker #{id} started and ready.")
    send(Process.whereis(JAIDE.Manager), {:worker_ready, self()})
    {:ok, %{id: id, status: :idle}}
  end

  @impl true
  def handle_cast({:run_task, task, start_time}, state) do
    Logger.info("Worker #{state.id} received task: #{inspect(task)}")
    # Simulate heavy computation by calling external polyglot code
    result = execute_task(task)
    send(Process.whereis(JAIDE.Manager), {:task_complete, self(), result, start_time})
    # After sending result, signal readiness for a new task
    send(Process.whereis(JAIDE.Manager), {:worker_ready, self()})
    {:noreply, %{state | status: :busy}}
  end

  # --- Private Functions ---
  defp execute_task({:tensor_op, op, a, b}) do
    # This would be an FFI call to the Zig tensorcore library
